const { withAppBuildGradle, withGradleProperties } = require('@expo/config-plugins');

/**
 * Release signing for the Android app.
 *
 * `android/` is generated by `expo prebuild`, so the signing configuration has to
 * be applied as a plugin rather than edited by hand — otherwise the next prebuild
 * silently drops it and the release build falls back to the debug key.
 *
 * The keystore path and passwords are read from gradle properties, which come
 * from the environment (REVORA_RELEASE_*) so a CI build can supply its own
 * without them being committed. The local defaults point at the development
 * keystore checked in beside the app; a Play Store release should use Play App
 * Signing with an upload key managed outside this repository.
 */
const path = require('path');

// Outside `android/`, which `expo prebuild --clean` deletes.
const LOCAL_KEYSTORE = path.join(__dirname, '..', 'credentials', 'revora-release.keystore');

const DEFAULTS = {
  storeFile: LOCAL_KEYSTORE,
  storePassword: 'revora-release',
  keyAlias: 'revora',
  keyPassword: 'revora-release',
};

const SIGNING_BLOCK = `
        release {
            storeFile file(REVORA_RELEASE_STORE_FILE)
            storePassword REVORA_RELEASE_STORE_PASSWORD
            keyAlias REVORA_RELEASE_KEY_ALIAS
            keyPassword REVORA_RELEASE_KEY_PASSWORD
        }
`;

const withReleaseSigning = (config) => {
  config = withGradleProperties(config, (cfg) => {
    const entries = [
      ['REVORA_RELEASE_STORE_FILE', process.env.REVORA_RELEASE_STORE_FILE ?? DEFAULTS.storeFile],
      ['REVORA_RELEASE_STORE_PASSWORD', process.env.REVORA_RELEASE_STORE_PASSWORD ?? DEFAULTS.storePassword],
      ['REVORA_RELEASE_KEY_ALIAS', process.env.REVORA_RELEASE_KEY_ALIAS ?? DEFAULTS.keyAlias],
      ['REVORA_RELEASE_KEY_PASSWORD', process.env.REVORA_RELEASE_KEY_PASSWORD ?? DEFAULTS.keyPassword],
    ];

    for (const [key, value] of entries) {
      const existing = cfg.modResults.find((item) => item.type === 'property' && item.key === key);
      if (existing) existing.value = value;
      else cfg.modResults.push({ type: 'property', key, value });
    }
    return cfg;
  });

  return withAppBuildGradle(config, (cfg) => {
    let contents = cfg.modResults.contents;

    if (!contents.includes('REVORA_RELEASE_STORE_FILE')) {
      // Add the release signing config beside the generated debug one.
      contents = contents.replace(
        /signingConfigs\s*\{/,
        (match) => `${match}${SIGNING_BLOCK}`,
      );
    }

    // Point the release build type at it instead of the debug key.
    contents = contents.replace(
      /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
      '$1signingConfig signingConfigs.release',
    );

    cfg.modResults.contents = contents;
    return cfg;
  });
};

module.exports = withReleaseSigning;
